package com.franco.desco.adapter.in.web.delivery;import io.swagger.v3.oas.annotations.media.Schema;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class DeliveryResponses{private DeliveryResponses(){}@Schema(name="DeliveryCreatedResponse")public record Created(Long entregaSocioId){}@Schema(name="DeliverySummaryResponse")public record Summary(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoBrutoKg,BigDecimal taraKg,BigDecimal pesoRechazadoKg,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String estadoProceso,Long operativoVentaId,String operativo,Long socioId,String numeroDocumento,String socioNombre,BigDecimal valorizacion){}@Schema(name="DeliveryHeaderResponse")public record Header(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoBrutoKg,BigDecimal taraKg,BigDecimal pesoNetoKg,BigDecimal pesoRechazadoKg,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String ticketBalanza,String observacion,String estadoProceso,Long predioId,String predioCodigo,Long operativoVentaId,String operativo,String numeroDocumento,String socioNombre){}@Schema(name="DeliveryDetailLineResponse")public record DetailLine(Long entregaDetalleId,Integer variedadPaltaId,String variedad,Long condicionComercialId,String condicion,Long precioComercialId,BigDecimal kilogramos,BigDecimal precioBase,BigDecimal precioAplicado,BigDecimal importe){}@Schema(name="DeliveryIncidentResponse")public record Incident(Long incidenciaId,String tipoIncidencia,String severidad,BigDecimal pesoAfectadoKg,String descripcion,String estadoIncidencia){}@Schema(name="DeliveryFileResponse")public record File(Long archivoId,String nombreOriginal,String mimeType,String secureUrl,String categoria,String descripcion,Instant fechaCarga){}@Schema(name="DeliveryDetailResponse")public record Detail(Header entrega,List<DetailLine>detalles,List<Incident>incidencias,List<File>archivos){} }
